import { FormattedMessage, useIntl } from "react-intl";
import { getFocusAccessKeyId } from "components/DataSourceCredentialFields";
import { MAPPING_FIELDS } from "components/FocusMappingEditor";
import KeyValueLabel from "components/KeyValueLabel/KeyValueLabel";
import { FocusPropertiesProps } from "./types";

// The account ID of a FOCUS data source is generated by the API and means nothing to the user, so it is not shown
const FocusProperties = ({ config, createdAt }: FocusPropertiesProps) => {
  const intl = useIntl();

  const {
    bucket_name: bucketName,
    bucket_prefix: bucketPrefix,
    s3_endpoint: s3Endpoint,
    region_name: regionName,
    file_pattern: filePattern,
    mapping,
  } = config;

  const accessKeyId = getFocusAccessKeyId(config);

  // Fields overridden by the user mapping, in the order of the mapping editor
  const mappedFields = MAPPING_FIELDS.filter(({ apiName }) => mapping?.[apiName]).map(({ messageId }) =>
    intl.formatMessage({ id: messageId })
  );

  return (
    <>
      <KeyValueLabel
        keyMessageId="connectedAt"
        value={createdAt}
        dataTestIds={{
          key: "p_connected_at_id",
          value: "p_connected_at_value",
        }}
      />
      {bucketName ? (
        <>
          <KeyValueLabel
            keyMessageId="bucketName"
            value={bucketName}
            dataTestIds={{ key: "p_key_bucket_name", value: "p_value_bucket_name" }}
          />
          <KeyValueLabel
            keyMessageId="pathPrefix"
            value={bucketPrefix}
            dataTestIds={{ key: "p_key_bucket_prefix", value: "p_value_bucket_prefix" }}
          />
          <KeyValueLabel
            keyMessageId="s3Endpoint"
            value={s3Endpoint}
            dataTestIds={{ key: "p_key_s3_endpoint", value: "p_value_s3_endpoint" }}
          />
          <KeyValueLabel
            keyMessageId="region"
            value={regionName}
            dataTestIds={{ key: "p_key_region_name", value: "p_value_region_name" }}
          />
          <KeyValueLabel
            keyMessageId="focusAccess"
            value={
              accessKeyId ? (
                <FormattedMessage id="focusAccessKeys" values={{ accessKeyId }} />
              ) : (
                <FormattedMessage id="focusAnonymousAccess" />
              )
            }
            dataTestIds={{ key: "p_key_access", value: "p_value_access" }}
          />
          <KeyValueLabel
            keyMessageId="focusFilePattern"
            value={filePattern}
            dataTestIds={{ key: "p_key_file_pattern", value: "p_value_file_pattern" }}
          />
        </>
      ) : (
        <KeyValueLabel
          keyMessageId="bucketName"
          value={<FormattedMessage id="focusNoBucketManualUpload" />}
          dataTestIds={{ key: "p_key_bucket_name", value: "p_value_no_bucket" }}
        />
      )}
      <KeyValueLabel
        keyMessageId="focusMappedFields"
        value={mappedFields.length > 0 ? mappedFields.join(", ") : undefined}
        dataTestIds={{ key: "p_key_mapped_fields", value: "p_value_mapped_fields" }}
      />
    </>
  );
};

export default FocusProperties;
